import { useState, useCallback, memo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Settings as SettingsIcon, Monitor, Smartphone, Tv,
  ArrowLeft, Check, RefreshCw, Save, X, Eye,
  Palette, Type, LayoutGrid, List, Play,
  Download, Bell, Moon, Sun, Zap, Globe,
  HardDrive, Cpu, Clock, Shield, Info
} from 'lucide-react';
import { useSettings } from '../contexts/SettingsContext';
import { useToast } from '../contexts/ToastContext';

const THEMES = [
  { id: 'dark', name: 'Dark', colors: '#0a0a0f, #1a1a2e, #16213e' },
  { id: 'midnight', name: 'Midnight', colors: '#0c1929, #1a3a5c, #0c2d48' },
  { id: 'midnight-purple', name: 'Midnight Purple', colors: '#0d0d1a, #1a1a2e, #2d1b69' },
  { id: 'charcoal', name: 'Charcoal', colors: '#1a1a1a, #2d2d2d, #1a1a1a' },
  { id: 'navy', name: 'Navy', colors: '#0a1628, #1a2a4a, #0d1f3c' },
];

const RESOLUTION_OPTIONS = ['Auto', '4K', '1080p', '720p', '480p'];
const DEFAULT_SOURCES = ['vidstream', 'megacloud', 'streamtape', 'doodstream', 'upstream', 'fembed'];

function SettingsPageInner() {
  const navigate = useNavigate();
  const { settings, updateSetting, resetSettings } = useSettings();
  const { addToast } = useToast();
  const [activeTab, setActiveTab] = useState<'appearance' | 'streaming' | 'general' | 'about'>('appearance');
  const [showResetConfirm, setShowResetConfirm] = useState(false);

  const handleReset = useCallback(() => {
    resetSettings();
    addToast('Settings reset to defaults', 'success');
    setShowResetConfirm(false);
  }, [resetSettings, addToast]);

  const tabs = [
    { id: 'appearance' as const, label: 'Appearance', icon: Palette },
    { id: 'streaming' as const, label: 'Streaming', icon: Play },
    { id: 'general' as const, label: 'General', icon: SettingsIcon },
    { id: 'about' as const, label: 'About', icon: Info },
  ];

  return (
    <div className="min-h-screen bg-[#0a0a0f] pt-16">
      {/* Header */}
      <div className="sticky top-16 z-40 bg-[#0a0a0f]/95 backdrop-blur-xl border-b border-white/5">
        <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-4">
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate(-1)}
              className="p-2 text-white/50 hover:text-white hover:bg-white/10 rounded-lg transition-all"
            >
              <ArrowLeft size={20} />
            </button>
            <div>
              <h1 className="text-xl sm:text-2xl font-bold text-white flex items-center gap-2">
                <SettingsIcon size={22} className="text-emerald-400" />
                Settings
              </h1>
              <p className="text-white/40 text-sm">Customize your experience</p>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-6">
        {/* Tabs */}
        <div className="flex gap-1 mb-6 bg-white/5 p-1 rounded-xl overflow-x-auto">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium transition-all whitespace-nowrap flex-1 justify-center ${
                activeTab === tab.id
                  ? 'bg-emerald-500 text-white shadow-lg'
                  : 'text-white/50 hover:text-white hover:bg-white/5'
              }`}
            >
              <tab.icon size={16} />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Appearance Tab */}
        {activeTab === 'appearance' && (
          <div className="space-y-6">
            {/* Theme */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <Palette size={18} />
                Theme
              </h3>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
                {THEMES.map(theme => (
                  <button
                    key={theme.id}
                    onClick={() => updateSetting('theme', theme.id as any)}
                    className={`relative group rounded-xl overflow-hidden border-2 transition-all ${
                      settings.theme === theme.id
                        ? 'border-emerald-400 shadow-lg shadow-emerald-500/20'
                        : 'border-white/10 hover:border-white/20'
                    }`}
                  >
                    <div className="h-20">
                      <div className="h-full flex">
                        {theme.colors.split(',').map((color, i) => (
                          <div key={i} className="flex-1" style={{ backgroundColor: color.trim() }} />
                        ))}
                      </div>
                    </div>
                    <div className="p-2 bg-black/50 backdrop-blur-sm">
                      <p className="text-white text-xs font-medium text-center">{theme.name}</p>
                    </div>
                    {settings.theme === theme.id && (
                      <div className="absolute top-1 right-1 w-5 h-5 bg-emerald-400 rounded-full flex items-center justify-center">
                        <Check size={12} className="text-black" />
                      </div>
                    )}
                  </button>
                ))}
              </div>
            </div>

            {/* Display */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <Monitor size={18} />
                Display
              </h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-medium text-sm">Card Layout</p>
                    <p className="text-white/40 text-xs">Choose how content cards are displayed</p>
                  </div>
                  <div className="flex items-center gap-1 bg-white/5 rounded-lg p-1">
                    <button
                      onClick={() => updateSetting('listView', false)}
                      className={`p-2 rounded transition-all ${
                        !settings.listView
                          ? 'bg-emerald-500 text-white'
                          : 'text-white/50 hover:text-white'
                      }`}
                    >
                      <LayoutGrid size={16} />
                    </button>
                    <button
                      onClick={() => updateSetting('listView', true)}
                      className={`p-2 rounded transition-all ${
                        settings.listView
                          ? 'bg-emerald-500 text-white'
                          : 'text-white/50 hover:text-white'
                      }`}
                    >
                      <List size={16} />
                    </button>
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-medium text-sm">Show Details on Hover</p>
                    <p className="text-white/40 text-xs">Display movie details when hovering over cards</p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      checked={settings.showDetailsOnHover}
                      onChange={e => updateSetting('showDetailsOnHover', e.target.checked)}
                      className="sr-only peer"
                    />
                    <div className="w-11 h-6 bg-white/10 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500"></div>
                  </label>
                </div>

                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-medium text-sm">Show Rating on Cards</p>
                    <p className="text-white/40 text-xs">Display vote average on media cards</p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      checked={settings.showRatings}
                      onChange={e => updateSetting('showRatings', e.target.checked)}
                      className="sr-only peer"
                    />
                    <div className="w-11 h-6 bg-white/10 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500"></div>
                  </label>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Streaming Tab */}
        {activeTab === 'streaming' && (
          <div className="space-y-6">
            {/* Default Source */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <Play size={18} />
                Default Stream Source
              </h3>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {DEFAULT_SOURCES.map(source => (
                  <button
                    key={source}
                    onClick={() => updateSetting('defaultStreamSource', source)}
                    className={`px-4 py-2.5 rounded-lg text-sm font-medium transition-all ${
                      settings.defaultStreamSource === source
                        ? 'bg-emerald-500 text-white'
                        : 'bg-white/5 text-white/50 hover:bg-white/10 hover:text-white border border-white/5'
                    }`}
                  >
                    {source.charAt(0).toUpperCase() + source.slice(1)}
                  </button>
                ))}
              </div>
            </div>

            {/* Resolution */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <Monitor size={18} />
                Default Resolution
              </h3>
              <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
                {RESOLUTION_OPTIONS.map(res => (
                  <button
                    key={res}
                    onClick={() => updateSetting('resolution', res)}
                    className={`px-4 py-2.5 rounded-lg text-sm font-medium transition-all ${
                      settings.resolution === res
                        ? 'bg-emerald-500 text-white'
                        : 'bg-white/5 text-white/50 hover:bg-white/10 hover:text-white border border-white/5'
                    }`}
                  >
                    {res}
                  </button>
                ))}
              </div>
            </div>

            {/* Playback */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <Zap size={18} />
                Playback
              </h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-medium text-sm">Default Speed</p>
                    <p className="text-white/40 text-xs">Choose your preferred playback speed</p>
                  </div>
                  <select
                    value={settings.playbackSpeed}
                    onChange={e => updateSetting('playbackSpeed', parseFloat(e.target.value))}
                    className="bg-white/5 border border-white/10 text-white text-sm rounded-lg px-4 py-2.5 focus:outline-none focus:border-white/20 cursor-pointer"
                  >
                    {[0.5, 0.75, 1, 1.25, 1.5, 1.75, 2].map(speed => (
                      <option key={speed} value={speed} className="bg-[#1a1a2e]">
                        {speed}x
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* General Tab */}
        {activeTab === 'general' && (
          <div className="space-y-6">
            {/* Reset */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <RefreshCw size={18} />
                Reset Settings
              </h3>
              <p className="text-white/40 text-sm mb-4">
                Reset all settings to their default values. This cannot be undone.
              </p>
              {showResetConfirm ? (
                <div className="flex gap-2">
                  <button
                    onClick={handleReset}
                    className="flex items-center gap-2 px-4 py-2.5 bg-red-500 hover:bg-red-400 text-white rounded-lg transition-all text-sm font-medium"
                  >
                    <Check size={14} />
                    Confirm Reset
                  </button>
                  <button
                    onClick={() => setShowResetConfirm(false)}
                    className="flex items-center gap-2 px-4 py-2.5 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all text-sm font-medium"
                  >
                    <X size={14} />
                    Cancel
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setShowResetConfirm(true)}
                  className="flex items-center gap-2 px-4 py-2.5 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all text-sm font-medium"
                >
                  <RefreshCw size={14} />
                  Reset to Defaults
                </button>
              )}
            </div>

            {/* Data */}
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
                <HardDrive size={18} />
                Data Storage
              </h3>
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-sm">Watchlist</span>
                  <span className="text-white/30 text-sm">
                    {(() => {
                      try {
                        const ids = localStorage.getItem('watchlist-ids');
                        return ids ? JSON.parse(ids).length : 0;
                      } catch { return 0; }
                    })()} items
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-sm">History</span>
                  <span className="text-white/30 text-sm">
                    {(() => {
                      try {
                        const data = localStorage.getItem('viewing-history');
                        return data ? JSON.parse(data).length : 0;
                      } catch { return 0; }
                    })()} items
                  </span>
                </div>
                <button
                  onClick={() => {
                    localStorage.removeItem('viewing-history');
                    addToast('History cleared', 'info');
                  }}
                  className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 text-white/60 hover:text-white rounded-lg transition-all text-sm"
                >
                  <Download size={14} />
                  Clear History
                </button>
              </div>
            </div>
          </div>
        )}

        {/* About Tab */}
        {activeTab === 'about' && (
          <div className="space-y-6">
            <div className="bg-white/5 border border-white/5 rounded-2xl p-6 text-center">
              <div className="w-20 h-20 mx-auto mb-4 rounded-2xl bg-gradient-to-br from-emerald-400 to-emerald-600 flex items-center justify-center shadow-xl shadow-emerald-500/20">
                <span className="text-3xl font-black text-white">S</span>
              </div>
              <h2 className="text-2xl font-black text-white mb-1">StinkFlix</h2>
              <p className="text-white/30 text-sm mb-6">Version 2.0.0</p>
              <p className="text-white/40 text-sm max-w-md mx-auto leading-relaxed">
                A modern streaming platform that lets you watch movies and TV shows from multiple stream sources with a beautiful, responsive interface.
              </p>
              <div className="mt-6 flex flex-wrap items-center justify-center gap-3 text-white/30 text-xs">
                <span className="flex items-center gap-1"><Shield size={12} /> Privacy First</span>
                <span className="flex items-center gap-1"><Globe size={12} /> Multi-Source</span>
                <span className="flex items-center gap-1"><Monitor size={12} /> Responsive</span>
                <span className="flex items-center gap-1"><Zap size={12} /> Fast</span>
              </div>
            </div>

            <div className="bg-white/5 border border-white/5 rounded-2xl p-6">
              <h3 className="text-white font-semibold mb-3 flex items-center gap-2">
                <Cpu size={18} />
                Technologies
              </h3>
              <div className="grid grid-cols-2 gap-2 text-sm">
                {[
                  { name: 'React', ver: '19.x' },
                  { name: 'TypeScript', ver: '5.x' },
                  { name: 'Vite', ver: '7.x' },
                  { name: 'Tailwind', ver: '4.x' },
                  { name: 'React Router', ver: '7.x' },
                  { name: 'Lucide Icons', ver: 'latest' },
                ].map(tech => (
                  <div key={tech.name} className="flex items-center justify-between bg-white/5 rounded-lg px-3 py-2">
                    <span className="text-white/60">{tech.name}</span>
                    <span className="text-white/30 text-xs">{tech.ver}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default memo(SettingsPageInner);